  `delete_flag` varchar(1) NOT NULL DEFAULT '0' COMMENT '软删除标记',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_material_instance_code` (`unit_code`),
  KEY `idx_material_instance_sku_depot` (`material_extend_id`,`inbound_depot_id`),
  KEY `idx_material_instance_material` (`material_id`),
  KEY `idx_material_instance_inbound_item` (`inbound_item_id`),
  KEY `idx_material_instance_outbound_item` (`outbound_item_id`),
  KEY `idx_material_instance_status_depot` (`status`,`inbound_depot_id`),
  KEY `idx_material_instance_tenant_delete` (`tenant_id`,`delete_flag`),
  KEY `idx_instance_tenant_sku_status_depot` (`tenant_id`,`material_extend_id`,`status`,`current_depot_id`,`delete_flag`),
  KEY `idx_instance_tenant_inbound_item` (`tenant_id`,`inbound_item_id`,`delete_flag`),
  KEY `idx_instance_tenant_outbound_item` (`tenant_id`,`outbound_item_id`,`delete_flag`)
) ENGINE=InnoDB AUTO_INCREMENT=3077 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='单件商品实物档案';
